  3484  {
  3485      WASMFuncType *param_type = func->func_type;
  3486      uint32 param_count = param_type->param_count;
  3487      uint8 *param_types = param_type->types;
  3488      uint32 local_count = func->local_count;
  3489      uint8 *local_types = func->local_types;
  3490      uint32 i, local_offset = 0;
  3491      uint64 total_size = sizeof(uint16) * ((uint64)param_count + local_count);
  3492
  3493      /*
  3494       * Only allocate memory when total_size is not 0,
  3495       * or the return value of malloc(0) might be NULL on some platforms,
  3496       * which causes wasm loader return false.
  3497       */
  3498      if (total_size > 0
  3499          && !(func->local_offsets =
  3500                   loader_malloc(total_size, error_buf, error_buf_size))) {
  3501          return false;
  3502      }
  3503
  3504      for (i = 0; i < param_count; i++) {
  3505          func->local_offsets[i] = (uint16)local_offset;
  3506          local_offset += wasm_value_type_cell_num(param_types[i]);
  3507      }
  3508
  3509      for (i = 0; i < local_count; i++) {
  3510          func->local_offsets[param_count + i] = (uint16)local_offset;
  3511          local_offset += wasm_value_type_cell_num(local_types[i]);
  3512      }
  3513
  3514      bh_assert(local_offset == func->param_cell_num + func->local_cell_num);
  3515      return true;
  3516  }
