  9884  {
  9885      int16 operand_offset = 0;
  9886      BranchBlock *block = (opcode == WASM_OP_ELSE) ? loader_ctx->frame_csp - 1
  9887                                                    : loader_ctx->frame_csp;
  9888      BlockType *block_type = &block->block_type;
  9889      uint8 *return_types = NULL;
  9890  #if WASM_ENABLE_GC != 0
  9891      WASMRefTypeMap *reftype_maps = NULL;
  9892      uint32 reftype_map_count;
  9893  #endif
  9894      uint32 return_count = 0, value_count = 0, total_cel_num = 0;
  9895      int32 i = 0;
  9896      int16 dynamic_offset, dynamic_offset_org, *frame_offset = NULL,
  9897                                                *frame_offset_org = NULL;
  9898
  9899  #if WASM_ENABLE_GC == 0
  9900      return_count = block_type_get_result_types(block_type, &return_types);
  9901  #else
  9902      return_count = block_type_get_result_types(
  9903          block_type, &return_types, &reftype_maps, &reftype_map_count);
  9904  #endif
  9905
  9906      /* If there is only one return value, use EXT_OP_COPY_STACK_TOP/_I64/V128
  9907       * instead of EXT_OP_COPY_STACK_VALUES for interpreter performance. */
  9908      if (return_count == 1) {
  9909          uint8 cell = (uint8)wasm_value_type_cell_num(return_types[0]);
  9910          if (block->dynamic_offset != *(loader_ctx->frame_offset - cell)) {
  9911              /* insert op_copy before else opcode */
  9912              if (opcode == WASM_OP_ELSE)
  9913                  skip_label();
  9914  #if WASM_ENABLE_SIMDE != 0
  9915              if (cell == 4) {
  9916                  emit_label(EXT_OP_COPY_STACK_TOP_V128);
  9917              }
  9918  #endif
  9919              if (cell <= 2) {
  9920                  emit_label(cell == 1 ? EXT_OP_COPY_STACK_TOP
  9921                                       : EXT_OP_COPY_STACK_TOP_I64);
  9922              }
  9923              emit_operand(loader_ctx, *(loader_ctx->frame_offset - cell));
  9924              emit_operand(loader_ctx, block->dynamic_offset);
  9925
  9926              if (opcode == WASM_OP_ELSE) {
  9927                  *(loader_ctx->frame_offset - cell) = block->dynamic_offset;
  9928              }
  9929              else {
  9930                  loader_ctx->frame_offset -= cell;
  9931                  loader_ctx->dynamic_offset = block->dynamic_offset;
  9932                  PUSH_OFFSET_TYPE(return_types[0]);
  9933                  wasm_loader_emit_backspace(loader_ctx, sizeof(int16));
  9934              }
  9935              if (opcode == WASM_OP_ELSE)
  9936                  emit_label(opcode);
