 10024              if (cell == 4) {
 10025                  bool needs_copy = false;
 10026                  int16 v128_dynamic = dynamic_offset - cell;
 10027
 10028                  for (int k = 0; k < 4; k++) {
 10029                      if (*(frame_offset - k - 1) != (v128_dynamic + k)) {
 10030                          needs_copy = true;
 10031                          break;
 10032                      }
 10033                  }
 10034
 10035                  if (needs_copy) {
 10036                      cells[j] = cell;
 10037                      src_offsets[j] = *(frame_offset - cell);
 10038                      dst_offsets[j] = v128_dynamic;
 10039                      j++;
 10040                  }
 10041
 10042                  frame_offset -= cell;
 10043                  dynamic_offset = v128_dynamic;
 10044              }
 10045              else {
 10046                  frame_offset -= cell;
 10047                  dynamic_offset -= cell;
 10048                  if (dynamic_offset != *frame_offset) {
 10049                      cells[j] = cell;
 10050                      /* src offset */
 10051                      src_offsets[j] = *frame_offset;
 10052                      /* dst offset */
 10053                      dst_offsets[j] = dynamic_offset;
 10054                      j++;
 10055                  }
 10056              }
 10057
 10058              if (opcode == WASM_OP_ELSE) {
 10059                  if (cell == 4) {
 10060                      for (int k = 0; k < cell; k++) {
 10061                          *(frame_offset + k) = dynamic_offset + k;
 10062                      }
 10063                  }
 10064                  else {
 10065                      *frame_offset = dynamic_offset;
 10066                  }
 10067              }
 10068              else {
 10069                  loader_ctx->frame_offset = frame_offset;
 10070                  loader_ctx->dynamic_offset = dynamic_offset;
 10071                  if (!(wasm_loader_push_frame_offset(
 10072                          loader_ctx, return_types[i], disable_emit,
 10073                          operand_offset, error_buf, error_buf_size))) {
 10074                      wasm_runtime_free(emit_data);
 10075                      goto fail;
 10076                  }
 10077                  wasm_loader_emit_backspace(loader_ctx, sizeof(int16));
 10078                  loader_ctx->frame_offset = frame_offset_org;
 10079                  loader_ctx->dynamic_offset = dynamic_offset_org;
 10080              }
 10081          }
 10082
 10083          bh_assert(j == value_count);
 10084
 10085          /* Emit the cells, src_offsets and dst_offsets */
 10086          for (j = 0; j < value_count; j++)
 10087              emit_byte(loader_ctx, cells[j]);
 10088          for (j = 0; j < value_count; j++)
 10089              emit_operand(loader_ctx, src_offsets[j]);
 10090          for (j = 0; j < value_count; j++)
 10091              emit_operand(loader_ctx, dst_offsets[j]);
 10092
 10093          if (opcode == WASM_OP_ELSE)
 10094              emit_label(opcode);
 10095
 10096          wasm_runtime_free(emit_data);
 10097      }
 10098
 10099      return true;
